<!DOCTYPE html>
<html lang="en">

<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
  <title> Clinic Portal </title>
  <link rel="icon" type="image/png" sizes="64x64"
    href="data:image/png;base64," />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link
    href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600&display=swap"
    rel="stylesheet" />
  <link rel="stylesheet" href="../style/clinic_portal.css">
</head>

<body>

    <div class="portal-container">
        <div class="portal-header">
            <img src="../brand/logo.png" alt="logo" width="230rem" height="auto"/>
        </div>

        <div class="role-selection">
            <!-- Patient Portal Card -->
            <div class="role-card patient">
                <div>
                    <div class="role-title">Patient Portal</div>
                    <div class="role-desc">View your upcoming appointments and check laboratory results</div>
                </div>
                <span class="role-btn">Continue as Patient</span>
            </div>

            <!-- Admin Portal Card -->
            <div class="role-card admin">
                <div>
                    <div class="role-title">Admin Portal </div>
                    <div class="role-desc"> Lorem ipsum </div>
                </div>
                <span class="role-btn">Continue as Admin</span>
            </div>
        </div>
    </div>

</body>

</html>